import re
import logging


class ExpressionParser(object):
    _EXPRESSION_REG = r"\w[-\w<>!=:\./\s]+"

    def __init__(self):
        self._expression = ""
        self._field_expressions = {}
        self._logic_expression = ""

    def parse(self, expression):
        self._expression = self._format_logic_operator_in_expression(expression)
        self._find_all_expressions()
        logging.debug('{} {}'.format(self._logic_expression, self._field_expressions))
        return [self._logic_expression, self._field_expressions]

    @staticmethod
    def _format_logic_operator_in_expression(expression):
        if expression.startswith("not "):
            expression = " {}".format(expression)
        expression = expression.replace(" not ", "  not ")
        return expression.replace(' and ', '&&').replace(' or ', '||').replace(" not ", "!")

    def _find_all_expressions(self):
        expressions = re.findall(self._EXPRESSION_REG, self._expression)
        self._logic_expression = self._expression
        for index, field_expression in enumerate(expressions):
            field_expression = field_expression.strip()
            flag = "{}{}".format("E", index)
            self._field_expressions[flag] = field_expression
            self._logic_expression = self._logic_expression.replace(field_expression, '{{{}}}'.format(flag), 1)

        self._logic_expression = self._logic_expression.strip().\
            replace('&&', ' and ').replace('||', ' or ').replace("!", "not ")
